const orders = [
  { id: 1, status: 'paid', total: 120 },
  { id: 2, status: 'pending', total: 80 },
  { id: 3, status: 'paid', total: 200 }
];

const paidRevenue = orders
  .filter(o => o.status === 'paid')
  .map(o => o.total)
  .reduce((sum, n) => sum + n, 0);

console.log(paidRevenue); // 320

const users = [
  { name: 'Ada', team: 'eng' },
  { name: 'Lin', team: 'eng' },
  { name: 'Sam', team: 'sales' }
];

const byTeam = users.reduce((acc, user) => {
  (acc[user.team] ??= []).push(user.name);
  return acc;
}, {});

console.log(byTeam); // { eng: ['Ada','Lin'], sales: ['Sam'] }

